#!/usr/bin/env python3
"""Install the MVT tripwire application. Run from the existing project root.
No network calls, package installs, model changes, or Git commits are performed.
"""
import argparse
import os
from pathlib import Path
import tempfile

FILES = {
    'TRIPWIRE_SETUP.md': "# MVT virtual tripwire\n\nThis application adds a causal, single-target event detector after MVT inference. It does not alter training, model weights or benchmark code. Use trusted full tracker checkpoints only (the existing checkpoint loader uses PyTorch deserialization).\n\n## Install and test\n\nFrom the project root, in the existing working environment:\n\n```sh\npython -m pip install -e . --no-deps\npython -m pytest tests/test_tripwire.py -v\n```\n\n## Quick algorithm-only demo\n\n```sh\npython demo_tripwire.py --synthetic\n```\n\nThis uses synthetic ground-truth boxes, not MVT predictions. It should report two crossings with the default line and margin. Add `--browser-video` if ffmpeg with libx264 is available.\n\n## Actual MVT demo (GOT-10k)\n\n```sh\npython -u demo_tripwire.py --weights pretrained_models/MobileViT_Track_ep0100_weights_only.pth --sequence data/test/GOT-10k_Test_000001 --device auto --line 0.5 0 0.5 1 --margin 10 --fps 15\n```\n\nThe first row of the sequence's groundtruth.txt is used only for initialization. If unavailable, supply `--init-box X Y W H` (pixel XYWH) or `--select-roi` (desktop GUI). Add `--display` for desktop preview; Q stops the run. Image sequences are read from the sequence directory or its img/ subdirectory. Select a line before inference, and do not assume the target will cross it.\n\n## Actual MVT demo (video)\n\n```sh\npython -u demo_tripwire.py --weights pretrained_models/MobileViT_Track_ep0100_weights_only.pth --video sample.mp4 --select-roi --display --device auto --line 0.5 0 0.5 1\n```\n\nSelect the target on the first frame and press Enter. No automatic object detection or multi-object tracking is implemented. For headless environments use explicit `--init-box` and omit `--display` and `--select-roi`.\n\n## Outputs\n\nEach run writes to output/novelty_demo/<source-name>/ (or --output-dir). Rerunning the same source in the same output directory replaces its outputs. The MP4 contains the line, bounding box, trajectory and alerts; events.csv logs direction, confirmation frame and nominal time; predictions.txt stores XYWH boxes; summary.json records settings and measured timing. `--browser-video` additionally produces tripwire_browser.mp4 for notebook playback. Sequence FPS defaults to 15 (playback assumption), video FPS defaults to the source's reported FPS; nominal times are not exact timestamps for variable-frame-rate videos. Tracker FPS excludes frame acquisition, conversion and rendering; processing FPS includes these and encoding but excludes initialization and optional H.264 conversion. Synthetic tracker FPS is null.\n\n## Detection and evaluation\n\nThe two normalized endpoints define an infinite line, clipped visually by the image. Signed distance is positive on one side and negative on the other. The dead band is ±margin pixels. The stable side changes only when the centroid moves beyond the opposite margin; an invalid box or frame gap resets the side. A confirmation may lag the physical crossing; a tracker jump can trigger a false alarm. No confidence gating or world-coordinate calibration is implemented. The line is fixed in image space, so camera motion can produce apparent crossings.\n\nFor research, use validation videos with independently annotated crossing events, predefine boundaries, and compare margin 0 to nonzero margins. Report one-to-one matched event precision/recall/F1, false alarms, latency, and computational overhead. The synthetic demo verifies behavior, not MVT accuracy. Full GOT-10k test trajectories are not publicly annotated.\n",
    'demo_tripwire.py': '"""Track a single target and record fixed-boundary crossing events."""\nimport argparse\nimport csv\nimport json\nimport math\nimport re\nimport shutil\nimport subprocess\nimport time\nfrom collections import deque\nfrom dataclasses import asdict\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\n\nfrom mvt.applications.tripwire import VirtualTripwire, CrossingEvent\n\n\ndef natural_key(path):\n    return tuple((0, int(s)) if s.isdigit() else (1, s.lower())\n                 for s in re.split(r\'(\\d+)\', path.name))\n\n\ndef read_image(path):\n    image = cv2.imread(str(path))\n    if image is None:\n        raise RuntimeError(f\'Cannot read {path}\')\n    return image\n\n\ndef sequence_frames(folder):\n    folder = Path(folder)\n    if not folder.is_dir():\n        raise FileNotFoundError(folder)\n    root = folder / \'img\' if (folder / \'img\').is_dir() else folder\n    paths = sorted((p for p in root.iterdir() if p.is_file() and p.suffix.lower()\n                    in {\'.jpg\', \'.jpeg\', \'.png\', \'.bmp\'}), key=natural_key)\n    if not paths:\n        raise ValueError(f\'No images in {root}\')\n    for p in paths:\n        yield read_image(p)\n\n\ndef video_frames(cap):\n    while True:\n        ok, frame = cap.read()\n        if not ok:\n            break\n        yield frame\n\n\ndef synthetic_frames():\n    for i in range(150):\n        x = round(75 + 490 * (1 - abs(i - 74.5) / 74.5))\n        frame = np.full((360, 640, 3), (38, 48, 46), np.uint8)\n        for gy in range(0, 360, 40):\n            cv2.line(frame, (0, gy), (639, gy), (52, 64, 60), 1)\n        cv2.rectangle(frame, (x-25, 155), (x+25, 205), (180, 120, 50), -1)\n        yield frame, [x-25, 155, 50, 50]\n\n\ndef load_engine(args):\n    import torch\n    from mvt.models.mvt import MVT\n    from mvt.evaluation.tracker import MVTTracker\n    from mvt.training.pretrained import load_training_weights\n    device = (\'cuda\' if torch.cuda.is_available() else \'cpu\') if args.device == \'auto\' else args.device\n    if device == \'cuda\' and not torch.cuda.is_available():\n        raise RuntimeError(\'CUDA unavailable; use --device cpu\')\n    model = MVT()\n    print(load_training_weights(model, args.weights, backbone_only=False), flush=True)\n    engine = MVTTracker(model=model, device=device)\n    sync = torch.cuda.synchronize if device == \'cuda\' else lambda: None\n    return engine, sync, device\n\n\ndef valid_box(box, width, height):\n    VirtualTripwire.get_center(box)\n    x, y, w, h = box\n    if x < 0 or y < 0 or x+w > width or y+h > height:\n        raise ValueError(\'Initial box must lie inside the first frame\')\n    return list(map(float, box))\n\n\ndef choose_box(args, first):\n    if args.init_box is not None:\n        return args.init_box\n    if args.select_roi:\n        try:\n            return cv2.selectROI(\'Select target; Enter confirms\', first, False, False)\n        finally:\n            cv2.destroyAllWindows()\n    if args.sequence:\n        gt = args.sequence / \'groundtruth.txt\'\n        if gt.is_file():\n            with gt.open(encoding=\'utf-8-sig\') as f:\n                return [float(v) for v in re.split(r\'[,\\s]+\', f.readline().strip())]\n    raise ValueError(\'Provide --init-box X Y W H or --select-roi (desktop only)\')\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    source = p.add_mutually_exclusive_group(required=True)\n    source.add_argument(\'--sequence\', type=Path)\n    source.add_argument(\'--video\', type=Path)\n    source.add_argument(\'--synthetic\', action=\'store_true\', help=\'Algorithm demo only; no MVT inference\')\n    p.add_argument(\'--weights\', type=Path)\n    p.add_argument(\'--device\', choices=[\'auto\',\'cuda\',\'cpu\'], default=\'auto\')\n    p.add_argument(\'--line\', type=float, nargs=4, default=[.5,0,.5,1], metavar=(\'X1\',\'Y1\',\'X2\',\'Y2\'), help=\'Normalized infinite line, fixed before tracking\')\n    init = p.add_mutually_exclusive_group()\n    init.add_argument(\'--init-box\', type=float, nargs=4, metavar=(\'X\',\'Y\',\'W\',\'H\'))\n    init.add_argument(\'--select-roi\', action=\'store_true\', help=\'Desktop GUI: select first-frame target\')\n    p.add_argument(\'--margin\', type=float, default=10)\n    p.add_argument(\'--fps\', type=float, help=\'Sequence playback FPS (default 15); video uses source FPS unless overridden\')\n    p.add_argument(\'--trail\', type=int, default=100)\n    p.add_argument(\'--display\', action=\'store_true\', help=\'Desktop preview; Q stops\')\n    p.add_argument(\'--browser-video\', action=\'store_true\', help=\'Encode H.264 with ffmpeg if installed\')\n    p.add_argument(\'--output-dir\', type=Path, default=Path(\'output/novelty_demo\'))\n    args = p.parse_args()\n    if not args.synthetic and (args.weights is None or not args.weights.is_file()):\n        p.error(\'A valid full-model --weights checkpoint is required for real MVT inference\')\n    if args.synthetic and (args.weights or args.init_box or args.select_roi):\n        p.error(\'--synthetic supplies its own boxes; do not pass weights or initialization options\')\n    if not all(math.isfinite(v) and 0 <= v <= 1 for v in args.line):\n        p.error(\'--line coordinates must be finite and between 0 and 1\')\n    if not math.isfinite(args.margin) or args.margin < 0 or args.trail < 1:\n        p.error(\'Margin must be nonnegative and trail must be positive\')\n    if args.fps is not None and (not math.isfinite(args.fps) or args.fps <= 0):\n        p.error(\'--fps must be positive\')\n    if args.browser_video and not shutil.which(\'ffmpeg\'):\n        p.error(\'--browser-video requires ffmpeg on PATH\')\n    cap = None\n    writer = None\n    try:\n        if args.synthetic:\n            frames = iter(synthetic_frames())\n            name = \'synthetic_algorithm_only\'\n            source_fps = 15.0\n        elif args.sequence:\n            frames = ((f, None) for f in sequence_frames(args.sequence))\n            name = args.sequence.name\n            source_fps = 15.0\n        else:\n            cap = cv2.VideoCapture(str(args.video))\n            if not cap.isOpened():\n                raise RuntimeError(f\'Cannot open video {args.video}\')\n            frames = ((f, None) for f in video_frames(cap))\n            name = args.video.stem\n            source_fps = cap.get(cv2.CAP_PROP_FPS)\n            if not math.isfinite(source_fps) or source_fps <= 0:\n                if args.fps is None:\n                    raise ValueError(\'Unknown video FPS; provide --fps\')\n        fps = args.fps if args.fps is not None else source_fps\n        try:\n            first, synthetic_box = next(frames)\n        except StopIteration:\n            raise RuntimeError(\'Source contains no readable frames\') from None\n        height, width = first.shape[:2]\n        a = (args.line[0]*(width-1), args.line[1]*(height-1))\n        b = (args.line[2]*(width-1), args.line[3]*(height-1))\n        wire = VirtualTripwire(a, b, args.margin)\n        initial = valid_box(synthetic_box if args.synthetic else choose_box(args, first), width, height)\n        engine = None\n        sync = lambda: None\n        device = \'none (synthetic)\'\n        if not args.synthetic:\n            engine, sync, device = load_engine(args)\n            engine.initialize(cv2.cvtColor(first, cv2.COLOR_BGR2RGB), initial)\n            sync()\n        # Even dimensions prevent silent cropping by common video encoders.\n        out_w, out_h = width + width % 2, height + height % 2\n        out = args.output_dir / name\n        out.mkdir(parents=True, exist_ok=True)\n        video_path = out / \'MVT_tripwire.mp4\'\n        if args.synthetic:\n            video_path = out / \'synthetic_tripwire.mp4\'\n        writer = cv2.VideoWriter(str(video_path), cv2.VideoWriter_fourcc(*\'mp4v\'), fps, (out_w,out_h))\n        if not writer.isOpened():\n            raise RuntimeError(\'Cannot create output video\')\n        reach = 2*math.hypot(width,height)\n        v = np.array([wire.dx,wire.dy])/wire.length\n        draw_a = tuple(np.rint(np.array(a)-reach*v).astype(int))\n        draw_b = tuple(np.rint(np.array(b)+reach*v).astype(int))\n        trail = deque(maxlen=args.trail)\n        alert_until = 0\n        inference_seconds = application_seconds = 0.0\n        tracked = count = invalid = 0\n        stopped = False\n        started = time.perf_counter()\n        from itertools import chain\n        with (out/\'events.csv\').open(\'w\', newline=\'\', encoding=\'utf-8\') as ef, (out/\'predictions.txt\').open(\'w\', encoding=\'utf-8\') as pf:\n            log = csv.DictWriter(ef, fieldnames=list(CrossingEvent.__dataclass_fields__))\n            log.writeheader()\n            for n, (frame, supplied) in enumerate(chain([(first,synthetic_box)], frames), 1):\n                if frame.shape[:2] != (height,width):\n                    raise ValueError(f\'Frame {n} dimensions changed\')\n                if n == 1:\n                    box = initial\n                elif args.synthetic:\n                    box = supplied\n                else:\n                    rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)\n                    sync(); t = time.perf_counter()\n                    box = engine.track(rgb)[\'target_bbox\']\n                    sync(); inference_seconds += time.perf_counter()-t\n                    tracked += 1\n                t = time.perf_counter()\n                event = wire.update(box,n,fps)\n                application_seconds += time.perf_counter()-t\n                if event:\n                    log.writerow(asdict(event)); ef.flush()\n                    alert_until = n + round(2*fps) - 1\n                    print(f\'ALERT | frame={n} | t={event.timestamp:.2f}s | {event.direction}\', flush=True)\n                cv2.line(frame, draw_a, draw_b, (0,0,255), 2)\n                try:\n                    cx,cy = wire.get_center(box)\n                    x,y,w,h = map(lambda k: round(float(k)),box)\n                    trail.append((round(cx),round(cy)))\n                    if len(trail)>1:\n                        cv2.polylines(frame,[np.array(trail,dtype=np.int32).reshape(-1,1,2)],False,(0,255,255),2)\n                    cv2.rectangle(frame,(x,y),(x+w,y+h),(0,255,0),2)\n                    cv2.circle(frame,(round(cx),round(cy)),4,(0,255,255),-1)\n                    pf.write(\',\'.join(f\'{float(k):.6f}\' for k in box)+\'\\n\')\n                except (ValueError,TypeError,OverflowError):\n                    invalid += 1; trail.clear(); pf.write(\'nan,nan,nan,nan\\n\')\n                alert = n <= alert_until\n                cv2.putText(frame,\'ALERT: TARGET CROSSED\' if alert else \'Monitoring target\',(10,25),cv2.FONT_HERSHEY_SIMPLEX,.6,(0,0,255) if alert else (255,255,255),2)\n                cv2.putText(frame,f\'Frame {n} | Crossings: {len(wire.events)}\',(10,50),cv2.FONT_HERSHEY_SIMPLEX,.5,(255,255,255),1)\n                if args.synthetic:\n                    cv2.putText(frame,\'SYNTHETIC - NO MVT INFERENCE\',(10,height-12),cv2.FONT_HERSHEY_SIMPLEX,.55,(255,255,255),2)\n                frame = cv2.copyMakeBorder(frame,0,out_h-height,0,out_w-width,cv2.BORDER_CONSTANT,value=(0,0,0))\n                writer.write(frame); count = n\n                if args.display:\n                    cv2.imshow(\'MVT Tripwire\',frame)\n                    if cv2.waitKey(1)&0xff == ord(\'q\'):\n                        stopped = True; break\n                if n%50 == 0:\n                    print(f\'Processed {n} frames\',flush=True)\n        writer.release(); writer = None\n        elapsed = time.perf_counter()-started\n        summary = dict(source=name, mode=\'synthetic_algorithm_only\' if args.synthetic else \'mvt_inference\', device=device,\n                       weights=str(args.weights) if args.weights else None, frames=count, crossings=len(wire.events), invalid_boxes=invalid,\n                       stopped_by_user=stopped, playback_fps=fps, margin_pixels=args.margin, line_normalized=args.line,\n                       initial_bbox=initial, tracker_fps=tracked/inference_seconds if inference_seconds else None,\n                       tripwire_ms_per_frame=1000*application_seconds/count if count else None,\n                       processing_fps=count/elapsed if elapsed else None,\n                       timing_note=\'Processing FPS includes frame acquisition, overlays and encoding; excludes initialization and H264 conversion. Source timestamps are nominal frame/FPS.\')\n        if args.browser_video:\n            browser = out/\'tripwire_browser.mp4\'\n            subprocess.run([\'ffmpeg\',\'-y\',\'-loglevel\',\'error\',\'-i\',str(video_path),\'-c:v\',\'libx264\',\'-pix_fmt\',\'yuv420p\',\'-movflags\',\'+faststart\',str(browser)],check=True)\n        (out/\'summary.json\').write_text(json.dumps(summary,indent=2),encoding=\'utf-8\')\n        print(json.dumps(summary,indent=2)); print(f\'Outputs: {out.resolve()}\')\n    finally:\n        if writer is not None:\n            writer.release()\n        if cap is not None:\n            cap.release()\n        if args.display:\n            cv2.destroyAllWindows()\n\n\nif __name__ == \'__main__\':\n    main()\n',
    'src/mvt/applications/__init__.py': '',
    'src/mvt/applications/tripwire.py': '"""Causal, hysteresis-based crossing detection for an infinite image line."""\nfrom dataclasses import dataclass\nimport math\n\n\n@dataclass(frozen=True)\nclass CrossingEvent:\n    frame_number: int\n    timestamp: float\n    direction: str\n    center_x: float\n    center_y: float\n    signed_distance: float\n\n\nclass VirtualTripwire:\n    def __init__(self, point_a, point_b, margin=10.0):\n        self.a = tuple(map(float, point_a))\n        self.b = tuple(map(float, point_b))\n        if len(self.a) != 2 or len(self.b) != 2:\n            raise ValueError(\'Endpoints must be XY pairs\')\n        self.dx = self.b[0] - self.a[0]\n        self.dy = self.b[1] - self.a[1]\n        self.length = math.hypot(self.dx, self.dy)\n        self.margin = float(margin)\n        if not math.isfinite(self.length) or self.length <= 0:\n            raise ValueError(\'Tripwire endpoints must be finite and distinct\')\n        if not math.isfinite(self.margin) or self.margin < 0:\n            raise ValueError(\'Margin must be finite and nonnegative\')\n        self.reset()\n\n    def reset(self):\n        self.previous_side = None\n        self.last_frame = 0\n        self.events = []\n\n    @staticmethod\n    def get_center(bbox):\n        x, y, w, h = map(float, bbox)\n        if not all(map(math.isfinite, (x, y, w, h))) or w <= 0 or h <= 0:\n            raise ValueError(\'Invalid XYWH box\')\n        return x + w / 2, y + h / 2\n\n    def signed_distance(self, center):\n        x, y = center\n        return (self.dx * (y - self.a[1]) - self.dy * (x - self.a[0])) / self.length\n\n    def update(self, bbox, frame_number, fps):\n        if frame_number <= self.last_frame or not math.isfinite(fps) or fps <= 0:\n            raise ValueError(\'Frame numbers must increase and FPS must be positive\')\n        if frame_number != self.last_frame + 1:\n            self.previous_side = None\n        self.last_frame = frame_number\n        try:\n            center = self.get_center(bbox)\n        except (ValueError, TypeError, OverflowError):\n            self.previous_side = None\n            return None\n        d = self.signed_distance(center)\n        side = 1 if d > self.margin else -1 if d < -self.margin else 0\n        if side == 0:\n            return None\n        previous = self.previous_side\n        self.previous_side = side\n        if previous is None or previous == side:\n            return None\n        event = CrossingEvent(frame_number, (frame_number - 1) / fps,\n                              \'positive_to_negative\' if side == -1 else \'negative_to_positive\',\n                              *center, d)\n        self.events.append(event)\n        return event\n',
    'tests/test_tripwire.py': "import pytest\nfrom mvt.applications.tripwire import VirtualTripwire\n\n\ndef box(x):\n    return [x-5, 45, 10, 10]\n\n\ndef run(xs, margin=5):\n    w = VirtualTripwire((100, 0), (100, 200), margin)\n    for i, x in enumerate(xs, 1):\n        w.update(box(x), i, 10)\n    return w.events\n\n\ndef test_no_crossing():\n    assert run([20, 50, 80]) == []\n\n\ndef test_bidirectional():\n    events = run([80, 98, 120, 121, 80])\n    assert [e.frame_number for e in events] == [3, 5]\n    assert [e.direction for e in events] == ['positive_to_negative', 'negative_to_positive']\n    assert events[0].timestamp == pytest.approx(.2)\n\n\ndef test_jitter():\n    assert run([80, 97, 101, 99, 105, 80]) == []\n    assert len(run([80, 101, 99, 103, 97, 80], 0)) == 4\n\n\ndef test_neutral_initialization():\n    assert run([100, 101, 120]) == []\n\n\ndef test_invalid_and_gap():\n    w = VirtualTripwire((100, 0), (100, 200))\n    w.update(box(80), 1, 10)\n    w.update([0, 0, -1, 2], 2, 10)\n    assert w.update(box(120), 3, 10) is None\n    assert w.update(box(80), 5, 10) is None\n    with pytest.raises(ValueError):\n        w.update(box(80), 5, 10)\n\n\ndef test_invalid_config():\n    with pytest.raises(ValueError):\n        VirtualTripwire((1, 1), (1, 1))\n    with pytest.raises(ValueError):\n        VirtualTripwire((1, 1), (2, 2), -1)\n",
}


MARKERS = ('pyproject.toml', 'evaluate_mvt.py', 'src/mvt/evaluation/tracker.py',
           'src/mvt/models/mvt.py', 'src/mvt/training/pretrained.py')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path.cwd())
    parser.add_argument('--check', action='store_true', help='Preview only; no writes')
    args = parser.parse_args()
    root = args.root.resolve()
    missing = [p for p in MARKERS if not (root / p).is_file()]
    if missing:
        parser.error('Not the expected MVT repository root. Missing: ' + ', '.join(missing))
    pending = []
    conflicts = []
    for name, content in FILES.items():
        path = root / name
        data = content.encode('utf-8')
        if not path.resolve().is_relative_to(root) or path.is_symlink():
            conflicts.append(name + ' (unsafe path)')
        elif path.exists():
            if path.is_file() and path.read_bytes().replace(b'\r\n', b'\n') == data:
                print('UNCHANGED', name)
            else:
                conflicts.append(name)
        else:
            print('CREATE   ', name)
            pending.append((path, data))
    if conflicts:
        parser.error('Refusing to overwrite existing files: ' + ', '.join(conflicts) + '. No files changed.')
    if args.check:
        print(f'Preview: {len(pending)} new file(s). Nothing changed.')
        return
    created = []
    try:
        for path, data in pending:
            path.parent.mkdir(parents=True, exist_ok=True)
            # Exclusive creation avoids clobbering files added after preflight.
            with path.open('xb') as f:
                created.append(path)
                f.write(data)
    except BaseException:
        for path in reversed(created):
            path.unlink(missing_ok=True)
        raise
    print(f'Installed {len(created)} new file(s) in {root}')
    print('Next: python -m pip install -e . --no-deps')
    print('Test: python -m pytest tests/test_tripwire.py -v')
    print('Demo: python demo_tripwire.py --synthetic')
    print('Actual MVT instructions: TRIPWIRE_SETUP.md')


if __name__ == '__main__':
    main()
